window.NPC_CHUNK_176 = [{"name":"Interlocutor Kyton","cr":12,"xp":19200,"race":"interlocutor kyton","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["evil","extraplanar","kyton","lawful"],"init":7,"senses":["darkvision 60 ft."],"ac":26,"ac_touch":13,"ac_flat_footed":22,"ac_mods":"+3 Dex, +1 dodge, +13 natural, -1 size","hp":147,"hd":"14d10+70","hd_value":14,"hp_mods":"regeneration 5 (good weapons and spells, silver weapons)","fort":14,"ref":9,"will":17,"dr":"10/silver or good","immunities":["cold"],"sr":23,"speed":[{"type":"land","speed":40}],"melee":"4 claws +20 (1d8+7/19-20 plus bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"poison"},{"type":"rend","details":"2 claws, 1d8+7"},{"type":"surgical strikes"},{"type":"unnerving gaze","details":"30 ft.; DC 22"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"bleed"},{"spell":"plane shift","details":"self only, from the Material Plane to the Shadow Plane"},{"spell":"stabilize"}]},{"frequency":"1/day","spells":[{"spell":"breath of life"}]},{"frequency":"3/day","spells":[{"spell":"cure serious wounds"},{"spell":"restoration"}]}],"strength":24,"dexterity":17,"constitution":21,"intelligence":15,"wisdom":22,"charisma":20,"baseatk":14,"cmb":22,"cmd":36,"cmd_special":"38 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Heal","value":23},{"skill":"Intimidate","value":22},{"skill":"Knowledge (arcana, local, religion)","value":9},{"skill":"Knowledge (dungeoneering, nature, planes)","value":12},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":23},{"skill":"Stealth","value":16}],"languages":["Common","Infernal"],"special_abilities":[{"type":"Surgical Strikes","kind":"Ex","details":"An interlocutor's claws threaten a critical hit on a roll of 19-20. On a successful critical hit, that claw deals 2d6 bleed damage rather than 1d6."},{"type":"Unnerving Gaze","kind":"Ex","details":"A creature that succumbs to an interlocutor's unnerving gaze becomes staggered for 1 round as it becomes convinced that it recognizes some of its own body parts entangled in the interlocutor's body."}],"during_combat":"The interlocutor heads directly into melee, delivering full attacks to the most vulnerable opponent within reach. If combat goes well and it successfully strikes down an opponent, it may spend an action casting stabilize on that PC, even going so far as to cast breath of life to restore the final PC to life should the kyton wipe out the entire party-all so it has a potential experimental subject in its debt.","morale":"The terms of the kyton's binding don't allow for anything but a fight until its destruction.","source":"PFS S3-26, Pathfinder RPG Bestiary 3 174"},{"name":"Miakovna","cr":10,"xp":9600,"race":"lamia matriarch","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":2}],"alignment":"LE","size":"Large","type":"monstrous humanoid","sub_types":["shapechanger"],"init":5,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":14,"ac_flat_footed":21,"ac_mods":"+4 armor, +5 Dex, +8 natural, -1 size","hp":143,"hd":"12d10+2d6+70","hd_value":14,"fort":9,"ref":13,"will":15,"immunities":["mind-affecting effects"],"sr":21,"speed":[{"type":"climb","speed":40},{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"+1 scimitar +15 (1d6+6/15-20 plus 1 Wisdom drain on first hit each round), +1 whip +14 (1d3+6 nonlethal) or touch +17 (1d4 Wisdom drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"Wisdom drain"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"ventriloquism"}]},{"frequency":"3/day","spells":[{"spell":"deep slumber"},{"spell":"dream"},{"spell":"major image"},{"spell":"mirror image"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":8,"spellsknown_concentration":15,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"glyph of warding"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"bull's strength"},{"spell":"cure moderate wounds"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"divine favor"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"bloodline":"Arcane","strength":20,"dexterity":21,"constitution":21,"intelligence":14,"wisdom":18,"charisma":25,"baseatk":13,"cmb":19,"cmd":34,"cmd_special":"can't be tripped","feats":[{"feat":"Double Slice"},{"feat":"Eschew Materials"},{"feat":"Exotic Weapon Proficiency (whip)"},{"feat":"Extend Spell"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":22},{"skill":"Climb","value":13},{"skill":"Diplomacy","value":12},{"skill":"Disguise","value":12},{"skill":"Intimidate","value":20},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (religion)","value":19},{"skill":"Linguistics","value":4},{"skill":"Spellcraft","value":19},{"skill":"Swim","value":13},{"skill":"Use Magic Device","value":20}],"languages":["Common","Abyssal","Infernal","Shoanti","Thassilonian"],"sq":["arcane bond (ring)","bloodline arcana (+1 DC for metamagicked spells that increase spell level)","change shape (fixed Medium humanoid form; alter self )"],"special_abilities":[{"type":"Spells","details":"A lamia matriarch casts spells as a 6th-level sorcerer, and can cast spells from the cleric list as well as those normally available to a sorcerer. Cleric spells are considered arcane spells for a lamia matriarch."},{"type":"Wisdom Drain","kind":"Su","details":"A lamia matriarch drains 1d4 points of Wisdom each time she hits with her melee touch attack. The first time each round that she strikes a foe with a melee weapon, she also drains 1 point of Wisdom. A DC 23 Will save negates the Wisdom drain. Unlike with other kinds of ability drain attacks, a lamia matriarch doesn't heal damage when she uses her Wisdom drain. The save DC is Charisma-based."}],"gear":"+1 scimitar, +1 whip, ring of counterspells (invisibility purge), silver holy symbol, 700 gp worth of diamond dust, potion of cure serious wounds","before_combat":"Miakovna casts mage armor daily. As soon as she is warned by one of her alarm spells going off, she casts invisibility and slithers up to the top of the north-central pillar. She then casts the following spells in order: stoneskin, shield of faith, bull's strength, mirror image, extended divine favor, and extended haste. If she hears the PCs attempting to enter the chamber before she is prepared, she creates a major image as described above and continues preparing, using her ventrilloquism spell-like ability to throw her voice elsewhere in the room as she casts spells, and recasting major image as needed to keep the distraction going.","during_combat":"Once all her spells are in place, she draws her whip and drops down to attack with both weapons, using the whip to trip opponents at range while slashing at closer foes with her scimitar. She stays in melee until she loses 50 or more hit points, at which point she climbs a pillar, recasts invisibility, and slithers around interlocking wings of Lissala's idols to keep her position hidden while healing and recasting protective spells. If presented with one particularly formidable opponent, Miakovna uses charm monster or suggestion to try and get the PC to leave combat.","morale":"When reduced to 30 or fewer hit points, Miakovna attempts to flee, swimming straight across the pool and racing up through the levels of the temple complex. As soon as she is out of sight of the PCs, she uses her change  shape ability, hoping that if the PCs catch her in this form, they'll assume it is another distraction and leave her alone.","source":"PFS S3-26, Pathfinder RPG Bestiary 2 175"},{"name":"Miakovna Subtier 10-11","cr":13,"xp":25600,"race":"lamia matriarch","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":5}],"alignment":"LE","size":"Large","type":"monstrous humanoid","sub_types":["shapechanger"],"init":5,"senses":["darkvision 60 ft.","low-light vision"],"ac":27,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 armor, +5 Dex, +9 natural, -1 size","hp":173,"hd":"12d10+5d6+90","hd_value":17,"fort":10,"ref":14,"will":16,"immunities":["mind-affecting effects"],"sr":24,"speed":[{"type":"climb","speed":40},{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"+1 spell storing scimitar +16 (1d6+6/15-20 plus 1 wisdom drain on first hit each round), +1 spell storing whip +15 (1d3+6 nonlethal) or touch +18 (1d4 Wisdom drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"Wisdom drain"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"ventriloquism"}]},{"frequency":"3/day","spells":[{"spell":"deep slumber"},{"spell":"dream"},{"spell":"major image"},{"spell":"mirror image"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":11,"spellsknown_concentration":19,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike"},{"spell":"waves of fatigue"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"cure critical wounds"},{"spell":"stoneskin"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"eagle's splendor"},{"spell":"glyph of warding"},{"spell":"haste"},{"spell":"inflict serious wounds"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"acid arrow"},{"spell":"blur"},{"spell":"bull's strength"},{"spell":"cure moderate wounds"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"divine favor"},{"spell":"identify"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"bloodline":"Arcane","strength":20,"dexterity":21,"constitution":21,"intelligence":14,"wisdom":18,"charisma":26,"baseatk":14,"cmb":20,"cmd":35,"cmd_special":"can't be tripped","feats":[{"feat":"Double Slice"},{"feat":"Eschew Materials"},{"feat":"Exotic Weapon Proficiency (whip)"},{"feat":"Extend Spell"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Quicken Spell"},{"feat":"Quicken Spell-Like Ability (mirror image)"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":25},{"skill":"Climb","value":13},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":13},{"skill":"Intimidate","value":23},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (religion)","value":21},{"skill":"Linguistics","value":4},{"skill":"Spellcraft","value":21},{"skill":"Swim","value":13},{"skill":"Use Magic Device","value":21}],"languages":["Common","Abyssal","Infernal","Shoanti","Thassilonian"],"sq":["arcane bond (ring)","bloodline arcana (+1 DC for  metamagic spells that increase spell level)","change shape (fixed Medium humanoid form; alter self )","metamagic adept (1/day)"],"special_abilities":[{"type":"Energy Drain","kind":"Su","details":"A lamia matriarch drains 1d4 points of Wisdom each time she hits with her melee touch attack. The first time each round that she strikes a foe with a melee weapon, she also drains 1 point of Wisdom. A DC 22 Will save negates the Wisdom drain. Unlike with other kinds of ability drain attacks, a lamia matriarch doesn't heal damage when she uses her Wisdom drain. The save DC is Charisma-based."},{"type":"Spells","details":"A lamia matriarch casts spells as a 6th-level sorcerer, and can cast spells from the cleric list as well as those normally available to a sorcerer. Cleric spells are considered arcane spells for a lamia matriarch."}],"gear":"+1 spell storing scimitar (inflict serious wounds), +1 spell storing whip (inflict serious wounds), amulet of natural armor +1, ring of counterspells (invisibility purge), silver holy symbol, 700 gp worth of diamond dust, potion of protection from energy (fire)","before_combat":"Miakovna casts mage armor daily. As soon as she is warned by one of her alarm spells going off, she casts invisibility and slithers up to the top of the northeastern pillar. She then casts the following spells in order: stoneskin, shield of faith, bull's strength, eagle's splendor, blur, extended divine favor, and extended haste. If she hears the PCs attempting to enter the chamber before she is prepared, she creates a major image as described above and continues preparing, using her ventriloquism spell-like ability to throw her voice elsewhere in the room as she casts spells, and recasting major image as needed to keep the distraction going.","during_combat":"Once all her spells are in place, she casts quickened mirror image and then targets the PCs with debilitating spells from atop the statue. When she feels they have been sufficiently softened, she draws her whip and drops down to attack with both weapons, using the whip to trip opponents at range while slashing at closer foes with her scimitar. She stays in melee until she loses 50 or more hit points, at which point she recasts invisibility and slithers around the room to hide her position while healing and recasting protective spells. When faced with one particularly overpowering foe, Miakovna uses charm monster or suggestion to get the PC to leave combat.","morale":"When reduced to 30 or fewer hit points, Miakovna attempts to flee, swimming straight across the pool and racing up through the levels of the temple complex. As soon as she is out of sight of the PCs, she uses change shape, hoping that if the PCs catch her in this form, they'll assume it is another distraction and leave her.","source":"PFS S3-26, Pathfinder RPG Bestiary 2 175"},{"name":"Freedom Town Assassin","cr":0.5,"xp":200,"race":"human","age_category":"Adult","classes":[{"class":"rogue","level":1}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 armor, +1 Dex","hp":10,"hd":"1d8+2","hd_value":1,"fort":2,"ref":3,"will":1,"speed":[{"type":"land","speed":30}],"melee":"liquid blade +2 (1d6+2/19-20 plus poison) or short sword +2 (1d6+2/19-20)","ranged":"light crossbow +1 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":15,"dexterity":12,"constitution":14,"intelligence":13,"wisdom":12,"charisma":8,"baseatk":0,"cmb":2,"cmd":13,"feats":[{"feat":"Combat Expertise"},{"feat":"Gang Up"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Bluff","value":3},{"skill":"Climb","value":6},{"skill":"Disable Device","value":5},{"skill":"Disguise","value":3},{"skill":"Escape Artist","value":5},{"skill":"Knowledge (local)","value":5},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":5},{"skill":"Stealth","value":5},{"skill":"Use Magic Device","value":3}],"languages":["Common","Orc"],"sq":["trapfinding +1"],"gear":"leather armor, light crossbow with 10 bolts, short sword, thieves' tools, beryl worth 50 gp, 4 gp, potion of cure light wounds, antitoxin, liquid blade, Small centipede poison (1 dose), smokestick","before_combat":"The assassins add a dose of small centipede poison to their liquid blades and activate the alchemical weapons before combat.","during_combat":"The assassins make frequent use of their Gang Up teamwork feat, picking off opponents by surrounding and stabbing them one at a time. If the assassins' liquid blades break or evaporate, they switch to their short swords.","morale":"If at least two of the assassins are defeated, the other two attempt to flee.","source":"AP 91"},{"name":"Patrol Sergeant Omast Frum","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"middle age","classes":[{"class":"fighter","level":5}],"alignment":"NG","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":17,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+6 armor, +1 deflection","hp":42,"hd":"5d10+10","hd_value":5,"fort":4,"ref":-1,"will":0,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"weaknesses":["alcoholic"],"speed":[{"type":"land","speed":30}],"melee":"mwk greatsword +8 (2d6+4/19-20)","ranged":"mwk heavy crossbow +4 (1d10-2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"heavy blades +1"}],"strength":15,"dexterity":10,"constitution":14,"intelligence":14,"wisdom":13,"charisma":9,"baseatk":5,"cmb":5,"cmb_special":"+7 reposition, +7 sunder","cmd":18,"cmd_special":"20 vs. reposition, 20 vs. sunder","feats":[{"feat":"Combat Expertise"},{"feat":"Improved Reposition"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Skill Focus (Heal)"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Climb","value":6},{"skill":"Handle Animal","value":2},{"skill":"Heal","value":7},{"skill":"Intimidate","value":5},{"skill":"Perception","value":4},{"skill":"Ride","value":2},{"skill":"Sense Motive","value":1},{"skill":"Swim","value":4}],"languages":["Common","Orc","Shoanti"],"sq":["armor training 1"],"special_abilities":[{"type":"Alcoholic","kind":"Ex","details":"Omast is currently drunk and suffering from moderate addiction to alcohol. While drunk, he is considered to be sickened. When not under the effects of alcohol, his addiction imparts a -2 penalty to his Strength and Constitution scores. Rules for drugs and addiction can be found on pages 236-237 of the Pathfinder RPG GameMastery Guide."}],"gear":"mwk breastplate, mwk greatsword, mwk heavy crossbow with 20 bolts, ring of protection +1, hip flask, potion of cure moderate wounds, smokesticks (2), thunderstones (2)","during_combat":"In combat, Omast repositions enemies around the battlefield, forcing them into positions where his allies can flank them or attack them from strategic locations. He sunders the weapons or armor of particularly tough enemies, though he is unafraid to attack and kill those he deems too great a threat to continue living.","morale":"Omast drinks his potion of cure moderate wounds if brought to fewer than 20 hit points, but he's willing to share his potion with allies in need as well. If he's reduced to fewer than 10 hit points, Omast attempts to retreat, though he stays and fights to the death to defend the lives of native Trunauans.","base_statistics":"When Omast is sober, his statistics are hp 37; Fort +5, Ref +1, Will +2; Melee mwk greatsword +9 (2d6+4/19-20); Ranged mwk heavy crossbow +6 (1d10/19-20); Str 13, Con 12; CMB +6 (+8 reposition, +8 sunder); CMD 17 (19 vs. reposition, 19 vs. sunder); Skills Climb +7, Handle Animal +4, Heal +9, Intimidate +7, Perception +6, Ride +4, Sense Motive +3, Swim +5. If cured of his alcohol addiction, Omast's statistics are Fort +6, Ref +1, Will +2; Melee mwk greatsword +10 (2d6+6/19-20); Ranged mwk heavy crossbow +6 (1d10/19-20); CMB +7 (+9 reposition, +9 sunder); Skills Climb +8, Handle Animal +4, Heal +9, Intimidate +7, Perception +6, Ride +4, Sense Motive +3, Swim +6.","source":"AP 91"},{"name":"Daktani","cr":2,"xp":600,"race":"half-Orc","gender":"Male","age_category":"middle age","classes":[{"class":"rogue","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":3,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex","hp":20,"hd":"3d8+3","hd_value":3,"fort":1,"ref":6,"will":1,"defensive_abilities":["evasion","Orc ferocity","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk morningstar +4 (1d8+1) or short sword +3 (1d6+1/19-20)","ranged":"dagger +5 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":16,"constitution":11,"intelligence":14,"wisdom":11,"charisma":9,"baseatk":2,"cmb":3,"cmb_special":"+5 dirty trick","cmd":16,"cmd_special":"18 vs. dirty trick","feats":[{"feat":"Combat Expertise"},{"feat":"Improved Dirty Trick"}],"skills":[{"skill":"Acrobatics","value":9,"special":"+4 when moving through a threatened square or enemy's space"},{"skill":"Bluff","value":5},{"skill":"Climb","value":7},{"skill":"Disable Device","value":10},{"skill":"Disguise","value":5},{"skill":"Intimidate","value":7},{"skill":"Knowledge (local)","value":8},{"skill":"Perception","value":6},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":9}],"languages":["Common","Giant","Hallit","Orc"],"sq":["Orc blood","rogue talents (cunning trigger)","trapfinding +1"],"gear":"leather armor, daggers (5), mwk morningstar, short sword, belt of tumbling, alchemically treated coals, crowbar, thieves' tools, key to area H14, garnet (worth 50 gp), 30 gp, potion of cure light wounds, potions of pass without trace (2), potion of vanish, smoke pellets (2), tangleburn bag","during_combat":"If forced to fight, Daktani tries to hinder opponents with dirty tricks and his tangleburn bag, flanking with Ghaer as much as possible to make sneak attacks. Daktani dodges around the basement and ruins above, both of which he knows quite well by now. He attempts to lead enemies into traps (using his cunning trigger rogue talent to set off the trap in area H10 if it hasn't yet been triggered), through monster-infested areas, and anywhere else hazardous enough to shake pursuers.","morale":"If Ghaer is defeated and Daktani is reduced to 5 hit  points or fewer, he tries to escape with the use of his smoke pellets or potion of vanish. If escape seems unlikely, the cowardly half-Orc lays down his weapons and surrenders.","source":"AP 91"},{"name":"Shadow Rat","cr":0.5,"xp":200,"race":"Shadow Rat","age_category":"Adult","alignment":"NE","size":"Tiny","type":"undead","init":2,"senses":["darkvision 60 ft.","scent"],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":5,"hd":"1d8+1","hd_value":1,"fort":1,"ref":2,"will":3,"defensive_abilities":["incorporeal form","shadow blend"],"immunities":["undead traits"],"speed":[{"type":"climb","speed":15},{"type":"land","speed":40}],"melee":"bite +4 (1d3-2 plus 1d2 Strength damage and disease)","space":"2-1/2 ft.","reach":"0 ft.","strength":6,"dexterity":15,"intelligence":2,"wisdom":12,"charisma":13,"baseatk":0,"cmb":0,"cmd":8,"cmd_special":"12 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":8},{"skill":"Stealth","value":14}],"special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Bite-injury; save Fort DC 11, onset 1d3 days, frequency 1/day, effect 1d3 Dex damage and 1d3 Con damage, cure 2 consecutive saves. The save DC is Charisma-based."},{"type":"Incorporeal Form","kind":"Su","details":"As a standard action a shadow rat can assume an incorporeal form. It can maintain this form for up to 1 hour per day. In this form, the shadow rat gains the incorporeal subtype and has AC 15, touch 15, flat-footed 13 (+1 deflection, +2 Dex, +2 size). The shadow rat can still bite corporeal opponents while in its incorporeal form, but its attack deals only Strength damage and doesn't cause hit point damage or disease."},{"type":"Shadow Blend","kind":"Su","details":"In any condition of illumination other than bright light, a shadow rat can disappear into the shadows as a move action, giving it total concealment (50% miss chance). Artificial illumination, even a light or continual flame spell, doesn't negate this ability; a daylight spell, however, does."},{"type":"Strength Damage","kind":"Su","details":"A shadow rat deals Strength damage to living foes it bites. A creature reduced to 0 Strength doesn't die but cannot move and is unconscious."}],"source":"AP 91, Tome of Horrors Complete 504"},{"name":"Kagak Of The Rolling Thunder","cr":2,"xp":600,"race":"Orc","gender":"Male","age_category":"Adult","classes":[{"class":"skald","level":3}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["Orc"],"init":4,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+6 armor, +1 shield","hp":23,"hd":"3d8+6","hd_value":3,"fort":4,"ref":1,"will":4,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":20}],"melee":"mwk battleaxe +4 (1d8+1/3)","ranged":"throwing axe +2 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage powers","details":"strength surge"},{"type":"raging song 8 rounds/day","details":"inspired rage [+2 Str/Con, +1 Will], song of marching"}],"spellsknown_caster":"skald","spellsknown_caster_level":3,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"ear-piercing scream"},{"spell":"hideous laughter"},{"spell":"lesser confusion"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"mending"},{"spell":"message"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":12,"dexterity":10,"constitution":12,"intelligence":11,"wisdom":12,"charisma":13,"baseatk":2,"cmb":3,"cmd":13,"feats":[{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (enchantment)"}],"skills":[{"skill":"Climb","value":3},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":7},{"skill":"Perform (percussion)","value":7},{"skill":"Spellcraft","value":4}],"languages":["Common","Orc"],"sq":["bardic knowledge +1","versatile performance (percussion)","weapon familiarity"],"gear":"mwk chainmail, mwk light steel shield, mwk battleaxe, throwing axes (5), antitoxin, war drums, potion of cure moderate wounds, scrolls of cause fear (2), scroll of charm person, scrolls of grease (2), scroll of remove fear, scrolls of summon monster I (2), wand of cure light wounds (24 charges), thunderstone","during_combat":"Although he has been beating his drums for quite a while, Kagak waits to begin his raging song, which gives his allies the benefits of inspired rage, until enemies enter the tower below. While the orcs under his command engage foes, Kagak casts spells such as ear-piercing scream, hideous laughter, and sleep. He uses his scrolls as needed, summoning monsters, instilling fear in his enemies, or charming opponents.","morale":"If reduced to fewer than 10 hit points, Kagak imbibes his potion of cure moderate wounds or uses his wand of cure light wounds to stay in the battle. He fights to the death.","source":"AP 91, Pathfinder RPG Bestiary 222, Pathfinder RPG Advanced Class Guide 49"},{"name":"Orc Beast-Tamer","cr":1,"xp":400,"race":"Orc","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["Orc"],"init":2,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":17,"hd":"2d10+2","hd_value":2,"fort":4,"ref":5,"will":1,"defensive_abilities":["ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"Orc double axe +2 (1d8+4/1d8+1/3)","ranged":"javelin +4 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"two-weapon"},{"type":"favored enemy","details":"humans +2"}],"strength":17,"dexterity":15,"constitution":12,"intelligence":6,"wisdom":12,"charisma":8,"baseatk":2,"cmb":5,"cmd":17,"feats":[{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (Orc double axe)"}],"skills":[{"skill":"Climb","value":8},{"skill":"Handle Animal","value":4},{"skill":"Intimidate","value":4},{"skill":"Perception","value":6},{"skill":"Stealth","value":7}],"languages":["Common","Orc"],"sq":["track +1","weapon familiarity","wild empathy +1"],"gear":"leather armor, javelins (3), Orc double axe, scabbard of honing, 36 gp, potions of cure light wounds (2), acid (2), caltrops","during_combat":"The Orc beast-tamer orders her dogs to attack any enemies as a move action, supporting them with thrown javelins. In melee, she attacks with her Orc double axe, focusing her attacks on Human opponents.","morale":"The Orc fights to the death.","source":"AP 91, Pathfinder RPG Bestiary 222"},{"name":"Urnsul","cr":2,"xp":600,"race":"half-Orc","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":1},{"class":"rogue","level":2,"archetype":"spy"}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":2,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 shield","hp":22,"hd":"1d10+2d8+3","hd_value":3,"fort":3,"ref":5,"will":1,"defensive_abilities":["evasion","Orc ferocity"],"speed":[{"type":"land","speed":30}],"melee":"mwk warhammer +6 (1d8+2/3)","ranged":"light crossbow +4 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":15,"dexterity":14,"constitution":13,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":2,"cmb":4,"cmd":16,"feats":[{"feat":"Fight On"},{"feat":"Power Attack"},{"feat":"Weapon Focus (warhammer)"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Disguise","value":5},{"skill":"Escape Artist","value":7},{"skill":"Intimidate","value":8},{"skill":"Knowledge (local)","value":4},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":8}],"languages":["Common","Giant","Orc"],"sq":["Orc blood","rogue talents (honeyed words)","skilled liar +1"],"gear":"mwk studded leather, light crossbow with 10 bolts, mwk warhammer, shield cloak, 7 gp, potion of vanish, alchemist's fire (2), thunderstone","during_combat":"Urnsul tries to set up flanking opportunities with Vorom to make sneak attacks, and she uses Power Attack with her warhammer as long as she successfully hits doing so.","morale":"Urnsul fights until reduced to 0 hit points, when her Fight On feat kicks in. At that point she attempts to escape using her potion of vanish. If flight seems unlikely, she surrenders instead.","source":"AP 91, Pathfinder RPG Advanced Player's Guide 135"},{"name":"Orc Bombardier","cr":1,"xp":400,"race":"Orc","age_category":"Adult","classes":[{"class":"fighter","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["Orc"],"init":2,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+4 armor, +2 Dex","hp":19,"hd":"2d10+4","hd_value":2,"fort":4,"ref":2,"will":-1,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1","ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":20}],"melee":"falchion +5 (2d4+4/18-20)","ranged":"composite shortbow +4 (1d6+3/3)","space":"5 ft.","reach":"5 ft.","strength":16,"dexterity":15,"constitution":13,"intelligence":12,"wisdom":8,"charisma":6,"baseatk":2,"cmb":5,"cmb_special":"+7 grapple","cmd":17,"cmd_special":"19 vs. grapple","feats":[{"feat":"Exotic Weapon Proficiency (light catapult)"},{"feat":"Improved Grapple"},{"feat":"Improved Unarmed Strike"}],"skills":[{"skill":"Craft (alchemy)","value":6},{"skill":"Knowledge (engineering)","value":6},{"skill":"Perception","value":1}],"languages":["Common","Giant","Orc"],"sq":["weapon familiarity"],"gear":"hide armor, composite shortbow (+3 Str) with 20 arrows, falchion, unerring grenade, alchemist's fire (2), smokesticks (2), tanglefoot bag","source":"AP 91, Pathfinder RPG Bestiary 222"},{"name":"Orc Shieldbreaker","cr":0.5,"xp":200,"race":"Orc","age_category":"Adult","classes":[{"class":"fighter","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["Orc"],"init":2,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":9,"hd":"1d10-1","hd_value":1,"fort":1,"ref":2,"will":0,"defensive_abilities":["ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"shotel +5 (1d8+4/3)","ranged":"pilum +3 (1d8+4)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":14,"constitution":8,"intelligence":8,"wisdom":11,"charisma":10,"baseatk":1,"cmb":5,"cmd":17,"feats":[{"feat":"Exotic Weapon Proficiency (shotel)"},{"feat":"Point-Blank Shot"}],"skills":[{"skill":"Climb","value":8},{"skill":"Intimidate","value":4}],"languages":["Common","Orc"],"sq":["weapon familiarity"],"gear":"leather armor, dagger, pilums (3), shotel, 3 gp, potion of cure light wounds, antitoxin, alchemist's fire (2)","during_combat":"The Orc shieldbreakers use their shotels to get around opponents' shields in melee and throw pilums at out-of-reach opponents.","source":"AP 91, Pathfinder RPG Bestiary 222"},{"name":"Crusher","cr":6,"xp":2400,"race":"cave giant","gender":"Male","age_category":"Adult","alignment":"CE","size":"Large","type":"humanoid","sub_types":["giant"],"init":0,"senses":["darkvision 120 ft.","low-light vision"],"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+3 armor, +6 natural, -1 size","hp":76,"hd":"9d8+36","hd_value":9,"fort":10,"ref":3,"will":3,"save_mods":"Will: +2 vs. violent temper per handler","defensive_abilities":["ferocity","rock catching"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +12 (1d8+6) or 2 chains (with orcs) +9 (2d6+6) or 2 chains (without orcs) +11 (1d8+6)","ranged":"rock +6 (1d8+6)","space":"10 ft.","reach":"10 ft. (20 ft. with chains)","special_attacks":[{"type":"flailing chains"},{"type":"rock throwing","details":"100 ft."},{"type":"violent temper"}],"strength":23,"dexterity":10,"constitution":19,"intelligence":6,"wisdom":10,"charisma":7,"baseatk":6,"cmb":13,"cmb_special":"+15 sunder","cmd":23,"cmd_special":"25 vs. sunder","feats":[{"feat":"Cleave"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (slams)"}],"skills":[{"skill":"Climb","value":4},{"skill":"Intimidate","value":8},{"skill":"Perception","value":6}],"languages":["Orc"],"sq":["axe wielder","handlers"],"special_abilities":[{"type":"Flailing Chains","kind":"Ex","details":"Because he has been shackled for most of his life, Crusher is highly capable of fighting using the chains of his manacles. Crusher's chain attacks deal different amounts of damage depending on whether or not orcs are still chained to his wrists. With attached orcs, Crusher takes a -2 on attack rolls with his chains. On a successful hit, the attached Orc takes damage equal to the amount of damage Crusher deals as the giant swings his allies wildly about and smashes them into opponents. If the attached orcs die, their bloody corpses fall off the chains after 1 round. Thereafter, Crusher makes chain attacks without attached orcs."},{"type":"Handlers","kind":"Ex","details":"Crusher requires the constant attention of four handlers-two Orc beast-tamers controlling his legs and two chained orcs controlling his arms. Normally, Crusher follows his leg handlers with little need for direction, allowing the beast-tamers to take normal actions during combat. The two orcs chained to his arms, however, must spend move actions to move with the giant and standard actions to direct Crusher's attacks. If not directed in this way, the giant takes no actions, moaning in pain or gazing listlessly at the blood on the battlefield until he eventually succumbs to his violent temper. For each Orc handler still conscious and attached to him, Crusher gains a cumulative +2 bonus on Will saves against his violent temper ability (maximum +8)."},{"type":"Violent Temper","kind":"Ex","details":"Crusher becomes violently enraged if he isn't tended to by his \"little green play-people.\" Each round of combat on his turn, Crusher must succeed at a DC 14 Will save or become enraged for 4 rounds. While enraged, Crusher gains the confused condition and doesn't follow the guidance of his handlers. He gains a +2 morale bonus to Strength and Constitution (including 9 additional hit points), a +1 morale bonus on Will saves, and a -2 penalty to Armor Class. Crusher always makes chain attacks while enraged. After raging, Crusher is fatigued for a number of rounds equal to the number of rounds spent enraged, and he cannot become enraged again while fatigued or exhausted. This effect is otherwise identical to a barbarian's rage."}],"gear":"broken breastplate","during_combat":"Crusher uses his slam attacks as directed by his Orc handlers until they are dead or until he succumbs to his violent temper, at which point he uses his chains-with or without attached orcs.","morale":"Crusher knows only pain, and he fights to the death.","source":"AP 91, Pathfinder RPG Bestiary 3 127","unique_monster":1},{"name":"Uskroth's Guardian","cr":5,"xp":1600,"race":"Hill giant","age_category":"Adult","alignment":"NE","size":"Large","type":"undead","sub_types":["giant"],"templates_applied":"@skeleton","init":4,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+6 armor, +2 natural, -1 size","hp":45,"hd":"10d8","hd_value":10,"fort":3,"ref":3,"will":7,"dr":"5/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"broken +1 spear +12 (2d6+9) or 2 claws +13 (1d6+7)","space":"10 ft.","reach":"10 ft.","strength":25,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":7,"cmb":15,"cmd":25,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"gear":"mwk chainmail, broken +1 spear","source":"AP 91, Pathfinder RPG Bestiary 150, 250"},{"name":"Kurst Grath","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cavalier","level":1},{"class":"ranger","level":4}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+4 armor, +3 Dex, +2 shield","hp":40,"hd":"5d10+9","hd_value":5,"fort":8,"ref":8,"will":3,"speed":[{"type":"land","speed":20}],"melee":"mwk longsword +6 (1d8+2/19-20), light shield +5 (1d3+1) or mwk longsword +8 (1d8+2/19-20)","ranged":"mwk composite longbow +9 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"challenge","details":"1/day, +1 attack rolls, +1 damage"},{"type":"combat style","details":"weapon and shield"},{"type":"favored enemy","details":"orcs +2"},{"type":"tactician","details":"1/day, standard action, 3 rounds, Swap Places"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":1,"spellsprepared_concentration":2,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"delay poison"}]}],"strength":14,"dexterity":16,"constitution":13,"intelligence":8,"wisdom":12,"charisma":12,"baseatk":5,"cmb":7,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Endurance"},{"feat":"Improved Shield Bash"},{"feat":"Mounted Combat"},{"feat":"Power Attack"},{"feat":"Swap Places"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Climb","value":5},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":8},{"skill":"Ride","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":8}],"languages":["Common"],"sq":["favored terrain (mountain +2)","hunter's bond (companions)","mount (horse named Hope)","order of the shield","track +2","wild empathy +5"],"gear":"mwk hide armor, +1 light steel shield, mwk composite longbow (+2 Str) with 20 arrows, mwk longsword, cloak of resistance +1, antitoxin, sunrods (3), tindertwigs (5), 19 gp, potions of cure light wounds (2), thunderstone","during_combat":"Kurst uses his bow if fighting at range, though if his foes attempt to close the gap, he jumps on his mount, Hope, and charges into battle with sword and shield. If he encounters orcs, Kurst activates his hunter's bond ability, and uses his tactician ability to grant allies use of Swap Places in combat.","morale":"If reduced to 20 or fewer hit points, Kurst drinks a potion of cure light wounds. If he has expended all of his healing options and the battle is clearly not favoring his side, he gathers up as many fallen allies as he can on his mount and calls for retreat. Few humanoids can keep up with Hope's speed, so Kurst directs the escape as best he can, regrouping his allies when they've reached safety and can plan their next course of action.","source":"AP 91, Pathfinder RPG Advanced Player's Guide 32"},{"name":"Skreed Gorewillow","cr":3,"xp":800,"race":"half-Orc","gender":"Male","age_category":"Adult","classes":[{"class":"alchemist","level":4}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":5,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+3 armor, +5 Dex, +2 natural","hp":29,"hd":"4d8+8","hd_value":4,"fort":5,"ref":9,"will":1,"save_mods":"+2 vs. poison","defensive_abilities":["Orc ferocity"],"dr":"10/magic vs. ranged (40 points)","speed":[{"type":"land","speed":30}],"melee":"mwk cold iron falchion +5 (2d4+1/18-20 plus poison [black adder venom]) or dagger +4 (1d4+1/19-20 plus poison [blue whinnis])","ranged":"bomb +9 (2d6+3 fire) or light crossbow +8 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"9/day, 2d6+3 fire and catch fire, DC 15, 10-ft. radius"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":4,"extractsprepared":[{"spell_level":2,"spells":[{"spell":"elemental touch"},{"spell":"protection from arrows"}]},{"spell_level":1,"spells":[{"spell":"bomber's eye","count":2},{"spell":"cure light wounds"},{"spell":"expeditious retreat"}]}],"strength":12,"dexterity":20,"constitution":13,"intelligence":16,"wisdom":6,"charisma":10,"baseatk":3,"cmb":4,"cmd":19,"feats":[{"feat":"Brew Potion"},{"feat":"Extra Bombs"},{"feat":"Iron Will"},{"feat":"Throw Anything"}],"skills":[{"skill":"Craft (alchemy)","value":11},{"skill":"Disable Device","value":14},{"skill":"Disguise","value":4},{"skill":"Intimidate","value":6},{"skill":"Knowledge (arcana)","value":8},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":10},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":7}],"languages":["Common","Giant","Orc","Ulfen","Varisian"],"sq":["alchemy (alchemy crafting +4)","discoveries (explosive bomb, precise bombs [3 squares])","mutagen (+4/-2, +2 natural, 40 minutes)","Orc blood","poison use","swift alchemy"],"gear":"mwk studded leather, mwk cold iron falchion, dagger, light crossbow with 10 bolts, formula alembic, kin's face tattoo, true love locket containing a lock of hair, alchemy crafting kit, antitoxin (2), formula book (contains all prepared extracts plus enlarge person, invisibility, shield, and stone fist), mwk thieves' tools, portable alchemist's lab, letter from Grenseldek, 37 gp, potion of cure moderate wounds, acid (2), alchemist's fire (2), black adder venom (2 doses), bloodroot (2 doses), blue whinnis, liquid ice (2), oil of taggit,  tanglefoot bag, thunderstones (2)","before_combat":"Skreed has poisoned his weapons. Before combat, he drinks his Dexterity mutagen and extract of protection from arrows.","during_combat":"Skreed drinks an extract of bomber's eye and attacks from range as long as he is able, throwing explosive bombs or alchemical splash weapons as needed and focusing his attacks on anyone who looks as if he'd pose a threat from a distance. He uses his precise bombs discovery to ensure his dire wolf allies take as little damage from his bombs as possible. If pressed into melee, Skreed attempts to flank with his wolf allies, reapplying black adder venom or bloodroot poison to his blades as a move action using swift alchemy as needed.","morale":"Skreed longs for the blood of his enemies, so he fights to the death against the PCs.","source":"AP 91, Pathfinder RPG Advanced Player's Guide 26"},{"name":"Lesser Host Devil","cr":3,"xp":800,"race":"Lesser Host Devil","age_category":"Adult","alignment":"LE","size":"Small","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":3,"senses":["darkvision 60 ft.","see in darkness"],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +2 natural, +1 size","hp":30,"hd":"4d10+8","hd_value":4,"fort":6,"ref":7,"will":0,"dr":"5/good","immunities":["fire","poison"],"resists":["acid 10","cold 10"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":5}],"melee":"mwk spear +7 (1d8+1), 2 claws +6 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"noxious breath"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"mage hand"},{"spell":"ventriloquism"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"imp 35%, level 3"}]}],"strength":13,"dexterity":17,"constitution":14,"intelligence":7,"wisdom":9,"charisma":8,"baseatk":4,"cmb":4,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Hover"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":11},{"skill":"Perception","value":6},{"skill":"Stealth","value":13}],"languages":["Infernal","telepathy 100 ft."],"sq":["shared senses","superior grappler","swarming"],"special_abilities":[{"type":"Noxious Breath","kind":"Su","details":"Three times per day, a gaav can exhale a breath that reeks of pure corruption upon a creature within 5 feet. The target must succeed at a DC 14 Fortitude save or be sickened for 1d4 rounds. The save DC is Constitution-based. Creatures that successfully save cannot be affected by the same gaav's noxious breath for 24 hours. A delay poison or neutralize poison spell removes the effect from the sickened creature. Creatures with immunity to poison are unaffected, and creatures resistant to poison receive their normal bonus on their saving throws. Once a gaav uses its breath weapon, it can't use it again until 1d4 rounds later."},{"type":"Shared Senses","kind":"Su","details":"All gaavs within 100 ft. of one another share the same senses. Thus, if one individual perceives something (for example, with a successful Perception check), all others within range are immediately aware of it. Senses are instantly relayed from one gaav or magaav to the next, allowing for the senses of a single devil to potentially spread through and inform an entire massive swarm instantly. It is still possible for a gaav to be surprised or flat-footed, even if other nearby gaavs are not."},{"type":"Superior Grappler","kind":"Ex","details":"A gaav can wield a weapon and still attempt grapple checks. If it's not wielding a weapon, a gaav gains a +4 bonus on grapple checks. In addition, it takes up to eight gaavs cooperatively to lift a creature that one or more of them is grappling; each gaav can lift up to 50 pounds and still fly without being impeded."},{"type":"Swarming","kind":"Ex","details":"Up to two gaavs can share the same space at the same time. If two gaavs in the same square attack the same foe, they are considered to be flanking that foe as if they were in opposite squares."}],"gear":"mwk spear","during_combat":"Once the PCs arrive, the gaavs focus their attacks almost entirely on them. The gaavs have already expended their noxious breath attacks and summoned imps (which were defeated before the PCs arrived).","morale":"If one of the gaavs is defeated, the other teleports back to Kelseph's encampment on its next turn to report the battle's outcome.","source":"Daughters Of Fury, Pathfinder Campaign Setting: Book of the Damned Volume I, Princes of Darkness 58"},{"name":"Vegazi","cr":2,"xp":600,"race":"half-Orc","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":3}],"alignment":"NG","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":2,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 shield","hp":21,"hd":"3d10","hd_value":3,"fort":2,"ref":5,"will":5,"defensive_abilities":["Orc ferocity"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +5 (1d6+1/19-20)","ranged":"composite longbow +5 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"archery"},{"type":"favored enemy","details":"orcs +2"}],"strength":12,"dexterity":15,"constitution":8,"intelligence":10,"wisdom":14,"charisma":15,"baseatk":3,"cmb":4,"cmd":16,"feats":[{"feat":"Endurance"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"}],"skills":[{"skill":"Climb","value":6},{"skill":"Handle Animal","value":8},{"skill":"Heal","value":8},{"skill":"Intimidate","value":4},{"skill":"Knowledge (geography)","value":5},{"skill":"Knowledge (nature)","value":5},{"skill":"Perception","value":8},{"skill":"Survival","value":7}],"languages":["Common","Orc"],"sq":["favored terrain (mountain +2)","Orc blood","track +1","wild empathy +5"],"gear":"mwk studded leather, light wooden shield, mwk short sword, composite longbow (+1 Str) with 20 arrows, dust of tracelessness, antitoxin (2), healer's kit, tindertwigs (5), Arwyll family signet ring worth 50 gp, +1 Orc-bane arrows (3), potion of bull's strength, acid (2), silver arrows (10), tanglefoot bag","source":"Daughters Of Fury"},{"name":"Ogash, The Steel Daughter","cr":3,"xp":800,"race":"Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"bloodrager","level":4}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+7 armor, +2 Dex, -2 bloodrage","hp":51,"hd":"4d10+20","hd_value":4,"fort":8,"ref":3,"will":2,"save_mods":"+2 vs. poison","defensive_abilities":["blood sanctuary","uncanny dodge"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"mwk Orc double axe +10 (1d8+6/x3)","ranged":"throwing axe +6 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bloodrage","details":"12 rounds/day"},{"type":"hellfire strike","details":"3/day, flaming"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"}]}],"spellsknown_caster":"bloodrager","spellsknown_caster_level":4,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"burning hands"},{"spell":"color spray"}]}],"bloodline":"infernal","strength":18,"dexterity":15,"constitution":19,"intelligence":12,"wisdom":8,"charisma":11,"baseatk":4,"cmb":8,"cmd":18,"feats":[{"feat":"Eschew Materials"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (Orc double axe)"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Bluff","value":2},{"skill":"Climb","value":8},{"skill":"Intimidate","value":7},{"skill":"Perception","value":6},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":6}],"languages":["Common","Infernal","Orc"],"sq":["blood casting","fast movement","fiendish sorcery"],"special_abilities":[{"type":"Fiendish Sorcery","kind":"Ex","details":"Because of Ogash's strong connection to the forces of Hell and her infernal bloodrager bloodline, her fiendish sorcery racial trait allows her to treat her Charisma score as 2 higher for the purpose of her bloodline powers."}],"gear":"+1 breastplate with armor spikes, mwk Orc double axe, throwing axes (3), black feather necklace worth 15 gp, climber's kit, hemp rope (50 ft.), locked gauntlet, mwk manacles, signal horn, 91 gp, potions of cure light wounds (2), potion of magic weapon, scrolls of magic missile (2), scroll of ray of enfeeblement, smokestick (3)","before_combat":"Ogash enters her bloodrage as soon as she knows she is about to face battle.","during_combat":"Ogash begins combat by using her darkness spell-like ability centered on Vegazi, then uses the effect as cover to attack the half-Orc and any PCs in the way. She prefers to fight in melee with her Orc double axe (making use of her hellfire strike to coat the weapon in flames), but hurls throwing axes at opponents who prove bothersome from a distance. She uses her scrolls and potions as needed.","morale":"Though Ogash is confident in her ability to abduct Vegazi and kill any who stand in her way, she isn't blind to her mortality. If her hell hound ally is slain, she attempts to abduct Vegazi and escape, heedless of the remaining combatants. If her ally is slain and she's reduced to fewer than 20 hit points, Ogash flees without Vegazi. However, if a PC is wearing Jagan's black feather necklace, Ogash attacks that PC exclusively and fights to the death.","base_statistics":"When not bloodraging, Ogash's statistics are AC 19, touch 12, flat-footed 17; hp 43; Fort +6, Will +0; Melee mwk Orc double axe +8 (1d8+3/x3); Ranged throwing axe +6 (1d6+2); Str 14, Con 15; CMB +6, CMD 18; Skills Climb +6.","source":"Daughters Of Fury, Pathfinder RPG Bestiary 264, Pathfinder RPG Advanced Class Guide 15"},{"name":"Ilka","cr":3,"xp":800,"race":"Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"druid","level":4}],"alignment":"NE","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+4 armor, +2 Dex, +1 shield","hp":37,"hd":"4d8+16","hd_value":4,"fort":7,"ref":3,"will":7,"save_mods":"+4 vs. fey and plant-targeted effects","resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"mwk scimitar +3 (1d6-1/18-20)","ranged":"sling +5 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"wild shape","details":"1/day"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":4,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"soften earth and stone"},{"spell":"summon swarm"},{"spell":"unshakable chill"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"entangle"},{"spell":"longstrider"},{"spell":"obscuring mist","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"light"},{"spell":"mending"},{"spell":"purify food and drink"},{"spell":"read magic"}]}],"strength":8,"dexterity":14,"constitution":17,"intelligence":12,"wisdom":16,"charisma":12,"baseatk":3,"cmb":2,"cmd":14,"feats":[{"feat":"Augment Summoning"},{"feat":"Spell Focus (conjuration)"}],"skills":[{"skill":"Bluff","value":3},{"skill":"Handle Animal","value":8},{"skill":"Knowledge (nature)","value":3},{"skill":"Perception","value":10},{"skill":"Ride","value":5},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":6},{"skill":"Survival","value":10}],"languages":["Common","Druidic","Infernal","Orc"],"sq":["fiendish sorcery","nature bond (animal companion)","nature sense","trackless step","wild empathy +5","woodland stride"],"gear":"mwk hide armor, mwk light wooden shield, mwk scimitar, silent whistle, necklace of black feathers worth 15 gp, 40 gp, potion of bear's endurance, scrolls of call animal (3), scroll of flame blade, scroll of flaming sphere, wand of charm animal (10 charges), wand of cure light wounds (12 charges), wand of magic fang (23 charges)","before_combat":"Before a potential combat, Ilka casts longstrider on herself. When she believes confrontation is imminent, she shifts to her natural form before drinking her potion of bear's endurance and using her wand of magic fang on Umber.","during_combat":"Ilka spontaneously casts summon nature's ally as often as possible to tip the odds in her favor. She casts unshakable chill on Vegazi to weaken her for capture, and she casts soften earth and stone to slow the PCs as she tries to knock the ranger unconscious. If she successfully subdues Vegazi, Ilka throws the half-Orc onto Umber and orders the boar to flee back to camp. Ilka uses her spells and scrolls as needed to keep the PCs busy or to cover her escape.","morale":"Ilka's primary goal is to capture Vegazi or a PC, and she flees if that doesn't seem like a possibility and her minions are defeated.","base_statistics":"Without her potion of bear's endurance or longstrider, Ilka's base statistics are hp 29; Fort +5; Speed 20 ft.; Con 13.","source":"Daughters Of Fury, Pathfinder RPG Bestiary 264"}];
